Here is a simple React component that provides autocomplete functionality. This component filters a list of suggestions based on the user's input.

```jsx
import React, { useState, useEffect } from 'react';

const Autocomplete = ({ suggestions, onChange }) => {
  const [value, setValue] = useState('');
  const [filteredSuggestions, setFilteredSuggestions] = useState([]);
  const [showSuggestions, setShowSuggestions] = useState(false);
  const [index, setIndex] = useState(-1);

  useEffect(() => {
    const handleInput = (e) => {
      const val = e.target.value;
      const tgt = e.target.selectionStart;
      const cur = val.slice(0, tgt);
      const nextVal = val.slice(tgt);

      if (val.length < 3) {
        setShowSuggestions(false);
      } else {
        const filtered = suggestions.filter((s) => {
          return s.toLowerCase().includes(cur.toLowerCase());
        });
        setFilteredSuggestions(filtered);
        setShowSuggestions(true);
      }
    };

    const handleSelect = (suggestion) => {
      const selection = suggestion + nextVal;
      setValue(selection);
      onChange(selection);
      setShowSuggestions(false);
    };

    const handleKeypress = (e) => {
      if (e.key === 'ArrowDown') {
        if (index < filteredSuggestions.length - 1) {
          setIndex(index + 1);
        }
      } else if (e.key === 'ArrowUp') {
        if (index > -1) {
          setIndex(index - 1);
        }
      } else if (e.key === 'Enter') {
        if (filteredSuggestions.length > 0) {
          handleSelect(filteredSuggestions[index]);
        }
      }
    };

    const input = document.getElementById('input');
    input.addEventListener('input', handleInput);
    input.addEventListener('keypress', handleKeypress);

    return () => {
      input.removeEventListener('input', handleInput);
      input.removeEventListener('keypress', handleKeypress);
    };
  }, [onChange, suggestions, value]);

  return (
    <div>
      <input id="input" type="text" value={value} onChange={(e) => setValue(e.target.value)} />
      {showSuggestions && (
        <ul>
          {filteredSuggestions.map((suggestion, i) => (
            <li
              key={i}
              onClick={() => handleSelect(suggestion)}
              className={i === index ? 'active' : ''}
            >
              {suggestion}
            </li>
          ))}
        </ul>
      )}
    </div>
  );
};

export default Autocomplete;
```

