using System;
using System.Net;
using System.Net.Http;
using System.Text;

class Program
{
    static void Main(string[] args)
    {
        // Création d'un HttpListener
        HttpListener listener = new HttpListener();
        listener.Prefixes.Add("http://localhost:8080/"); // Ajout de la plage d'adresse IP et du port

        // Démarrage du serveur
        listener.Start();

        Console.WriteLine("Serveur démarré, attendre des requêtes...");

        // Boucle principale pour accepter les requêtes
        while (true)
        {
            HttpListenerContext context = listener.GetContext();
            HttpListenerRequest request = context.Request;

            // Traitement de la requête
            if (request.Url.LocalPath == "/hello")
            {
                // Envoi de la réponse
                HttpResponse response = context.Response;
                response.StatusCode = 200;
                response.ContentLength64 = Encoding.ASCII.GetBytes("Hello").LongLength;
                using (Stream output = response.OutputStream)
                {
                    byte[] buffer = Encoding.ASCII.GetBytes("Hello");
                    output.Write(buffer, 0, buffer.Length);
                }
            }
            else
            {
                // Envoi d'une erreur 404
                HttpResponse response = context.Response;
                response.StatusCode = 404;
                response.StatusDescription = "Page not found";
            }
        }
    }
}
```
