    @Override
    public void classInitialize(JVMTIEnv env, JObject cl, JObject meth, JObject sig) {
        // Transform the Activity class's constructor
        JVMTIClassRef activityClass = env.GetClass("android/app/Activity");
        JVMTIMethodRef constructor = env.GetMethod(activityClass, "<init>", "()V");
        JVMTIStackFrame frame = env.CreateStackFrame(constructor, 0, 0, 0);
        env.QueryFrame(frame);
        env.SetReturnValue(frame, "Hello, transformed!");
