// Функция для вычисления интеграла методом прямоугольников
double integral_rectangle(int n, double a, double b, double (*f)(double)) {
    double h = (b - a) / n;
    double result = 0.0;
    for (int i = 1; i < n; i++) {
        result += f(a + i * h);
    }
    return h * (result + 0.5 * (f(a) + f(b)));
}

// Функция для вычисления интеграла методом трапеций
double integral_trap(int n, double a, double b, double (*f)(double)) {
    double h = (b - a) / n;
    double result = 0.0;
    for (int i = 1; i < n; i++) {
        result += f(a + i * h);
    }
    return h * (0.5 * (f(a) + f(b)) + result);
}

// Функция для вычисления интеграла методом Симпсона
double integral_simpson(int n, double a, double b, double (*f)(double)) {
    double h = (b - a) / n;
    double result = f(a) + f(b);
    for (int i = 1; i < n - 1; i++) {
        result += 2 * f(a + i * h);
    }
    return result * h / 3.0;
}

// Функция для вычисления интеграла с задержкой
