    Sleep(1000); // задержка для демонстрации многопоточности
    double integral = 0.0;
    switch (n % 3) {
        case 0: // метод прямоугольников
            integral = integral_rectangle(n, a, b, f);
            break;
        case 1: // метод трапеций
            integral = integral_trap(n, a, b, f);
            break;
        case 2: // метод Симпсона
            integral = integral_simpson(n, a, b, f);
            break;
    }
    // Синхронизация вывода в переменную
    WaitForSingleObject(hMutex, INFINITE);
    result = integral;
    ReleaseMutex(hMutex);
    ReleaseSemaphore(hSemaphore, 1, NULL);
}

