Here is a simple implementation of a Tic Tac Toe AI in JavaScript using the minimax algorithm:
```
// Tic Tac Toe Board
const board = ['', '', '', '', '', '', '', '', ''];

// Player symbols
const player1Symbol = 'X';
const player2Symbol = 'O';

// Function to print the board
function printBoard() {
  console.log(`
${board[0]} | ${board[1]} | ${board[2]}
---------
${board[3]} | ${board[4]} | ${board[5]}
---------
${board[6]} | ${board[7]} | ${board[8]}
`);
}

// Function to check if a cell is empty
function isEmpty(cell) {
  return cell === '';
}

// Function to check if the game is won
function isWon(symbol) {
  const winningCombinations = [
    [0, 1, 2],
    [3, 4, 5],
    [6, 7, 8],
    [0, 3, 6],
    [1, 4, 7],
    [2, 5, 8],
    [0, 4, 8],
    [2, 4, 6],
  ];

  for (const combination of winningCombinations) {
    if (
      board[combination[0]] === symbol &&
      board[combination[1]] === symbol &&
      board[combination[2]] === symbol
    ) {
      return true;
    }
  }

  return false;
}

// Function to check if the game is drawn
function isDraw() {
  return !board.includes('');
}

// Minimax AI function
function minimax(board, depth, isMaximizing) {
  if (isWon(player1Symbol)) {
    return -10 + depth;
  } else if (isWon(player2Symbol)) {
    return 10 - depth;
  } else if (isDraw()) {
    return 0;
  }

  let bestScore = -Infinity;

  if (isMaximizing) {
    for (let i = 0; i < 9; i++) {
      if (!isEmpty(board[i])) {
        continue;
      }

      board[i] = player2Symbol;
      const score = minimax(board, depth + 1, false);
      board[i] = '';

      bestScore = Math.max(score, bestScore);
    }

    return bestScore;
  } else {
    for (let i = 0; i < 9; i++) {
      if (!isEmpty(board[i])) {
        continue;
      }

      board[i] = player1Symbol;
      const score = minimax(board, depth + 1, true);
      board[i] = '';

      bestScore = Math.min(score, bestScore);
    }

    return bestScore;
  }
}

// Function to make the AI move
function AI_move() {
  let bestScore = -Infinity;
  let bestMove = 0;

  for (let i = 0; i < 9; i++) {
    if (!isEmpty(board[i])) {
      continue;
    }

    board[i] = player2Symbol;
    const score = minimax(board, 0, false);
    board[i] = '';

    if (score > bestScore) {
      bestScore = score;
      bestMove = i;
    }
  }

  board[bestMove] = player2Symbol;
}

// Game loop
function gameLoop() {
  printBoard();
  console.log('Player 1 turn:');
  const move = prompt('Enter your move (1-9):');
  board[move - 1] = player1Symbol;

  if (isWon(player1Symbol)) {
    printBoard();
    console.log('Player 1 wins!');
    return;
  } else if (isDraw()) {
    printBoard();
    console.log('It\'s a draw!');
    return;
  }

  AI_move();
  printBoard();
  console.log('Player 2 (AI) moves:');

  if (isWon(player2Symbol)) {
    printBoard();
    console.log('Player 2 (AI) wins!');
    return;
  }

  gameLoop();
}

gameLoop();
