```javascript
function uiSnackbar(icon, title, button, duration) {
    let snackbar = document.getElementById('snackbar');
    let num = 1;
    if (!snackbar) {
        const newDiv = document.createElement('div');
        newDiv.id = 'snackbar';
        newDiv.classList.add("ui_snackbar_wrapper");
        document.body.appendChild(newDiv);
        snackbar = newDiv;
    }
    let newId = `snackbar_message_${num}`; // присваивает уникальный id
    let template = new String(`
        <div class="ui_snackbar" id="${newId}">
            <div class="ui_snackbar__content">${icon ? `${icon}` : ''}${title}</div>
            ${button ? `${button}` : ''}
        </div>
    `);
    snackbar.insertAdjacentHTML('beforeend', template);

    num++; // при каждом вызове функции считает номер обратно

    setTimeout(function() {
        document.getElementById(newId).style.cssText = "opacity: 1; transform: translateY(0%); transition: opacity 200ms ease-in, transform 200ms cubic-bezier(0.175, 0.885, 0.32, 1.275);";
    }, 100);
    if (duration) {
        setTimeout(function() {
            document.getElementById(newId).style.cssText = "opacity: 0; transform: translateY(5%); transition: opacity 200ms ease-out, transform 200ms cubic-bezier(0.175, 0.885, 0.32, 1.275);";
        }, duration + 100);
        setTimeout(function() {
            document.getElementById(newId).parentNode.removeChild(document.getElementById(newId));
        }, duration + 300);
    }
}
```
